private def updateIfChanged(
    resultsToUpdate: Map[UUID, ResultEntity],
    referenceResults: Map[UUID, ResultEntity],
    uuid: UUID,
    result: ResultEntity,
): Map[UUID, ResultEntity] =
  referenceResults.get(uuid) match {
    case Some(oldResult) if isUnchanged(result, oldResult) =>
      resultsToUpdate
    case _ =>
      resultsToUpdate.updated(uuid, result)
  }
